import{_ as t,o as a,c as i,a2 as r}from"./chunks/framework.Crpw6aS5.js";const u=JSON.parse('{"title":"Desktop Open Project Targets Design","description":"","frontmatter":{},"headers":[],"relativePath":"superpowers/specs/2026-05-13-desktop-open-project-targets-design.md","filePath":"superpowers/specs/2026-05-13-desktop-open-project-targets-design.md","lastUpdated":1778654203000}'),o={name:"superpowers/specs/2026-05-13-desktop-open-project-targets-design.md"};function l(n,e,s,c,d,p){return a(),i("div",null,[...e[0]||(e[0]=[r('<h1 id="desktop-open-project-targets-design" tabindex="-1">Desktop Open Project Targets Design <a class="header-anchor" href="#desktop-open-project-targets-design" aria-label="Permalink to &quot;Desktop Open Project Targets Design&quot;">​</a></h1><h2 id="summary" tabindex="-1">Summary <a class="header-anchor" href="#summary" aria-label="Permalink to &quot;Summary&quot;">​</a></h2><p>Add a Codex app style project-open control to the desktop top-right toolbar. The control opens the project directory in a detected local IDE/editor or in the platform file manager. It must use the same directory the agent is actually working in, including a materialized session worktree, so the user never opens a different checkout from the one Claude is editing.</p><h2 id="goals" tabindex="-1">Goals <a class="header-anchor" href="#goals" aria-label="Permalink to &quot;Goals&quot;">​</a></h2><ul><li>Show a compact top-right toolbar button modelled after the Codex app UI: primary app icon plus a dropdown affordance when multiple targets exist.</li><li>Detect common local IDE/editor targets silently and display only installed, openable IDEs.</li><li>Always provide a platform file manager fallback: Finder on macOS, Explorer on Windows, and a generic file manager on Linux if supported.</li><li>Open the current session&#39;s effective working directory first. For active repository sessions this means the materialized worktree path when present; otherwise the session cwd/workDir. Before a session starts, use the launch workDir currently selected in the composer.</li><li>Keep this feature independent from Computer Use and from IDE MCP/extension connection state.</li><li>Avoid changing branches, creating worktrees, modifying repo state, or writing persistent user settings.</li></ul><h2 id="non-goals" tabindex="-1">Non-Goals <a class="header-anchor" href="#non-goals" aria-label="Permalink to &quot;Non-Goals&quot;">​</a></h2><ul><li>No external Terminal/iTerm/Warp launch in the first version.</li><li>No custom user-defined open commands.</li><li>No automatic IDE/plugin installation.</li><li>No H5/mobile browser access to local app launching.</li><li>No persistent global preference file in the first version. In-memory cache is enough.</li></ul><h2 id="current-code-context" tabindex="-1">Current Code Context <a class="header-anchor" href="#current-code-context" aria-label="Permalink to &quot;Current Code Context&quot;">​</a></h2><ul><li><code>desktop/src/components/layout/TabBar.tsx</code> already owns the top-right toolbar area with terminal and workspace-panel buttons.</li><li><code>desktop/src/components/shared/RepositoryLaunchControls.tsx</code> owns the pre-session workDir, branch, and worktree launch controls.</li><li>Active sessions expose working-directory context through session data, <code>SessionGitInfo</code>, and the existing <code>ProjectContextChip</code> usage in chat surfaces.</li><li>Server-side repository launch logic in <code>src/server/services/repositoryLaunchService.ts</code> already distinguishes source repo, requested workDir, and worktree path.</li><li>The current Tauri app already includes <code>@tauri-apps/plugin-shell</code> and <code>shell:allow-open</code>, but Tauri&#39;s current recommendation is the opener plugin for path/file-manager opening. The implementation plan can choose either a server API route or a Tauri command; the preferred design keeps platform detection and launching in the server/native boundary rather than scattering it through UI components.</li></ul><h2 id="product-behavior" tabindex="-1">Product Behavior <a class="header-anchor" href="#product-behavior" aria-label="Permalink to &quot;Product Behavior&quot;">​</a></h2><h3 id="toolbar-control" tabindex="-1">Toolbar Control <a class="header-anchor" href="#toolbar-control" aria-label="Permalink to &quot;Toolbar Control&quot;">​</a></h3><p>The top-right toolbar gets a new project-open control before the existing terminal/workspace buttons.</p><ul><li>If at least one IDE/editor is detected, show the highest-priority detected IDE as the primary icon and include a dropdown chevron.</li><li>If no IDE/editor is detected, show the platform file manager icon and behave as a single-click file-manager opener.</li><li>The dropdown only lists detected IDE/editor targets plus the file-manager fallback. It does not show unsupported or missing IDEs.</li><li>The visual style follows the Codex app reference: compact rounded segmented button, icon-first, subtle hover, dropdown menu with app icons and labels.</li></ul><h3 id="target-priority" tabindex="-1">Target Priority <a class="header-anchor" href="#target-priority" aria-label="Permalink to &quot;Target Priority&quot;">​</a></h3><p>Initial IDE/editor target registry:</p><ul><li>macOS: VS Code, Cursor, Sublime Text, Antigravity, GoLand, PyCharm, Finder.</li><li>Windows: VS Code, Cursor, Sublime Text, GoLand, PyCharm, Explorer.</li><li>Linux: VS Code, Cursor, Sublime Text, file manager fallback if available.</li></ul><p>Ordering:</p><ol><li>Last successfully opened IDE target during this app runtime, if still detected.</li><li>VS Code.</li><li>Cursor.</li><li>Antigravity.</li><li>Sublime Text.</li><li>GoLand.</li><li>PyCharm.</li><li>File manager fallback.</li></ol><p>The first version stores the last successful target only in memory.</p><h3 id="effective-path-resolution" tabindex="-1">Effective Path Resolution <a class="header-anchor" href="#effective-path-resolution" aria-label="Permalink to &quot;Effective Path Resolution&quot;">​</a></h3><p>The open path must match the agent&#39;s active working directory.</p><p>Resolution order:</p><ol><li>Active session materialized worktree path when present.</li><li>Active session cwd/workDir from session metadata.</li><li>Active session git workDir if exposed by <code>SessionGitInfo</code>.</li><li>Pre-session launch workDir selected in the composer.</li><li>No target path: disable the control and show no menu.</li></ol><p>The server revalidates the path before launching:</p><ul><li>It must exist.</li><li>It must be a directory.</li><li>It must not require any branch switch or worktree creation.</li></ul><h2 id="architecture" tabindex="-1">Architecture <a class="header-anchor" href="#architecture" aria-label="Permalink to &quot;Architecture&quot;">​</a></h2><h3 id="server-api" tabindex="-1">Server API <a class="header-anchor" href="#server-api" aria-label="Permalink to &quot;Server API&quot;">​</a></h3><p>Add a focused server API surface, tentatively under <code>src/server/api/open-targets.ts</code>.</p><p>Endpoints:</p><ul><li><code>GET /api/open-targets</code><ul><li>Returns platform, detected open targets, file-manager fallback, cache metadata.</li><li>Performs silent detection and uses a short in-memory cache.</li></ul></li><li><code>POST /api/open-targets/open</code><ul><li>Body: <code>{ targetId: string, path: string }</code>.</li><li>Validates the target is currently supported or is the file-manager fallback.</li><li>Validates the path is an existing directory.</li><li>Opens the path with the selected target.</li><li>Returns <code>{ ok: true, targetId, path }</code> or a typed error.</li></ul></li></ul><p>The route should be deny-by-default: only known target IDs from the registry are accepted.</p><h3 id="target-registry" tabindex="-1">Target Registry <a class="header-anchor" href="#target-registry" aria-label="Permalink to &quot;Target Registry&quot;">​</a></h3><p>Create a small registry with one responsibility: platform-specific detection and open command metadata.</p><p>Suggested module:</p><ul><li><code>src/server/services/openTargetService.ts</code></li></ul><p>Responsibilities:</p><ul><li>Define target IDs, display names, platform support, icon keys, detection candidates, and open behavior.</li><li>Detect installed/openable targets without requiring Computer Use Python helpers.</li><li>Cache detection results in memory for a short TTL.</li><li>Open the selected target using safe argument arrays, never shell-concatenated strings.</li></ul><p>Detection examples:</p><ul><li>macOS: <ul><li>Check common <code>.app</code> paths under <code>/Applications</code> and <code>~/Applications</code>.</li><li>For VS Code-family apps, also check CLI commands such as <code>code</code>, <code>cursor</code>, and <code>antigravity</code> when available.</li><li>Finder is always available.</li></ul></li><li>Windows: <ul><li>Check PATH commands such as <code>code.cmd</code>, <code>cursor.cmd</code>, <code>subl.exe</code>, and JetBrains launcher commands when available.</li><li>Check common install locations only where cheap and deterministic.</li><li>Explorer is always available.</li></ul></li><li>Linux: <ul><li>Check PATH commands for known targets.</li><li>Use <code>xdg-open</code> or platform file manager fallback only when available.</li></ul></li></ul><p>Opening examples:</p><ul><li>IDE/editor: launch known executable/CLI with the directory path as a single argument.</li><li>Finder/Explorer: <ul><li>macOS: <code>open &lt;path&gt;</code> or equivalent native opener.</li><li>Windows: <code>explorer.exe &lt;path&gt;</code>.</li><li>Linux: <code>xdg-open &lt;path&gt;</code> when available.</li></ul></li></ul><h3 id="desktop-ui" tabindex="-1">Desktop UI <a class="header-anchor" href="#desktop-ui" aria-label="Permalink to &quot;Desktop UI&quot;">​</a></h3><p>Create a dedicated component rather than expanding <code>TabBar.tsx</code> with detection logic.</p><p>Suggested files:</p><ul><li><code>desktop/src/api/openTargets.ts</code></li><li><code>desktop/src/stores/openTargetStore.ts</code></li><li><code>desktop/src/components/layout/OpenProjectMenu.tsx</code></li><li>tests next to the component/store or in existing desktop test locations.</li></ul><p>Responsibilities:</p><ul><li><code>openTargetsApi</code>: typed API client.</li><li><code>openTargetStore</code>: in-memory target list, loading/error state, short TTL, last successful target for this runtime.</li><li><code>OpenProjectMenu</code>: renders the Codex app style control and dropdown.</li><li><code>TabBar</code>: passes active-session path context into <code>OpenProjectMenu</code> and keeps layout ownership.</li></ul><p>The component should be disabled outside Tauri/desktop runtime and hidden if no valid path is available.</p><h2 id="error-handling" tabindex="-1">Error Handling <a class="header-anchor" href="#error-handling" aria-label="Permalink to &quot;Error Handling&quot;">​</a></h2><ul><li>Detection failure: keep Finder/Explorer fallback if platform supports it; do not block the toolbar.</li><li>Open target disappeared after cache: refresh targets once, then show a toast-style error if still unavailable.</li><li>Path missing: show a concise failure message and disable retry until session/path changes.</li><li>Unsupported target ID: server returns 400; UI treats it as stale cache and refreshes.</li><li>Command failure: server returns typed message with stderr redacted to a short detail.</li></ul><h2 id="testing" tabindex="-1">Testing <a class="header-anchor" href="#testing" aria-label="Permalink to &quot;Testing&quot;">​</a></h2><p>Server tests:</p><ul><li>Registry returns only installed/detected IDE targets plus file-manager fallback.</li><li>Missing IDEs are not returned.</li><li>File-manager fallback is returned when no IDE is detected.</li><li><code>POST /api/open-targets/open</code> rejects unknown target IDs.</li><li><code>POST /api/open-targets/open</code> rejects missing or non-directory paths.</li><li>Open command uses argument arrays and never shell-concatenated user paths.</li></ul><p>Desktop tests:</p><ul><li><code>OpenProjectMenu</code> shows IDE icon and dropdown when IDE targets exist.</li><li><code>OpenProjectMenu</code> degrades to Finder/Explorer single action when only file-manager fallback exists.</li><li>Missing targets are not rendered.</li><li><code>TabBar</code> renders the control for active session tabs and passes the effective worktree path.</li><li>Store caches target detection and refreshes after TTL or stale-target failure.</li></ul><p>Verification:</p><ul><li>Run narrow server tests for open-target service/API.</li><li>Run narrow desktop tests for <code>OpenProjectMenu</code>, store, and TabBar integration.</li><li>Run <code>bun run check:server</code> and <code>bun run check:desktop</code>.</li><li>Run <code>bun run verify</code> before final completion unless blocked by unrelated existing failures.</li></ul><h2 id="risks" tabindex="-1">Risks <a class="header-anchor" href="#risks" aria-label="Permalink to &quot;Risks&quot;">​</a></h2><ul><li>IDE command names differ by installation method, especially JetBrains and Windows. Mitigation: start with known common commands and deterministic app paths, keep fallback always available.</li><li>Tauri shell/open APIs differ from current recommendations. Mitigation: centralize opening server-side first; evaluate Tauri opener plugin only if the implementation needs native path reveal behavior.</li><li>Top-right toolbar can get crowded. Mitigation: compact icon-only control, dropdown only when useful, no text labels in toolbar.</li></ul><h2 id="references" tabindex="-1">References <a class="header-anchor" href="#references" aria-label="Permalink to &quot;References&quot;">​</a></h2><ul><li>Tauri Opener plugin docs: <a href="https://v2.tauri.app/plugin/opener/" target="_blank" rel="noreferrer">https://v2.tauri.app/plugin/opener/</a></li><li>Tauri Shell plugin docs: <a href="https://v2.tauri.app/zh-cn/plugin/shell/" target="_blank" rel="noreferrer">https://v2.tauri.app/zh-cn/plugin/shell/</a></li></ul>',61)])])}const g=t(o,[["render",l]]);export{u as __pageData,g as default};
